(() => {
 const get=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const views=[...document.querySelectorAll('.revision-view')],buttons=[...document.querySelectorAll('[data-view]')],checks=[...document.querySelectorAll('[data-check]')];
 const key='cs-atar-revision-checks-v1';let checked=new Set(),view='topics',active=null,submitted=false;
 try{checked=RevisionCore.restore(localStorage.getItem(key),revisionData.checkIds);get('save-message').textContent='Checklist progress is saved only in this browser.';}catch{get('save-message').textContent='Browser storage is unavailable. Ticks work for this page; export progress before leaving.';}
 function countChecks(){get('check-count').textContent=checks.filter(c=>c.dataset.kind==='requirement'&&c.checked).length+' syllabus-linked requirement self-checks ticked; these are not verified results.';}
 for(const c of checks){c.checked=checked.has(c.dataset.check);c.addEventListener('change',()=>{if(c.checked)checked.add(c.dataset.check);else checked.delete(c.dataset.check);try{localStorage.setItem(key,RevisionCore.serialize(checked));}catch{get('save-message').textContent='Progress could not be saved. Export it before leaving.';}countChecks();});}countChecks();
 function filter(){const unit=get('unit').value,q=get('query').value.trim().toLowerCase();let n=0;for(const card of document.querySelectorAll('#'+view+' .filter-card')){card.hidden=(unit!=='all'&&card.dataset.unit!==unit)||(q.length>0&&!card.textContent.toLowerCase().includes(q));if(!card.hidden)n++;}get('filter-count').textContent=n?'Showing '+n+' '+(view==='exams'?'questions':'topics'):'No matches. Choose all units or clear the search.';}
 function show(next){if(!views.some(v=>v.id===next))return;view=next;views.forEach(v=>v.hidden=v.id!==view);buttons.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===view)));document.querySelector('.filter-bar').hidden=!['topics','exams'].includes(view);filter();}
 buttons.forEach(b=>b.addEventListener('click',()=>show(b.dataset.view)));get('unit').addEventListener('change',filter);get('query').addEventListener('input',filter);
 function followHash(){const target=document.getElementById(location.hash.slice(1));if(!target)return;const section=target.closest('.revision-view');if(section){show(section.id);if(target.dataset.unit){get('unit').value=target.dataset.unit;get('query').value='';filter();}target.scrollIntoView();}}
 window.addEventListener('hashchange',followHash);show('topics');followHash();
 get('start-quiz').addEventListener('click',()=>{if(active&&!submitted)return;active=RevisionCore.quiz(revisionData,get('quiz-set').value);submitted=false;get('quiz-set').disabled=true;get('start-quiz').disabled=true;get('quiz-status').textContent='Answer before checking. Unanswered items will be reported separately.';get('quiz-form').innerHTML=active.map((q,n)=>`<fieldset class="quiz-question" id="quiz-${q.id}"><legend>${n+1}. ${esc(q.prompt)}</legend><p class="small">Unit ${q.unit} · syllabus-linked retrieval</p>${q.choices.map((c,i)=>`<label><input type="radio" name="${q.id}" value="${i}"> ${esc(c)}</label>`).join('')}<div id="feedback-${q.id}"></div></fieldset>`).join('')+'<button type="submit">Finish and check answers</button>';});
 get('quiz-form').addEventListener('submit',event=>{event.preventDefault();if(!active||submitted)return;const answers={};for(const q of active){const choice=document.querySelector(`input[name="${q.id}"]:checked`);if(choice)answers[q.id]=Number(choice.value);}const score=RevisionCore.grade(active,answers);submitted=true;for(const input of get('quiz-form').querySelectorAll('input'))input.disabled=true;get('quiz-form').querySelector('button[type="submit"]').disabled=true;get('quiz-set').disabled=false;get('start-quiz').disabled=false;get('quiz-status').textContent=`Practice recall: ${score.correct}/${score.total}; ${score.unanswered} unanswered. This is not a grade or a practical-skills result. Review explanations and revisit a changed case.`;for(const q of active){const value=answers[q.id],label=value===undefined?'Unanswered':value===q.correct?'Correct':'Revisit this idea';get('feedback-'+q.id).innerHTML=`<h3>${label}</h3><p><strong>Answer:</strong> ${esc(q.choices[q.correct])}</p><p>${esc(q.explanation)}</p>${value!==undefined&&value!==q.correct?'<p><strong>Your choice:</strong> '+esc(q.misconceptions[value])+'</p>':''}<details><summary>Why the other choices do not fit</summary><ul>${q.misconceptions.filter(Boolean).map(s=>'<li>'+esc(s)+'</li>').join('')}</ul></details><a href="../#${q.chapter}">Repair with the textbook</a>`;}get('quiz-status').scrollIntoView({block:'center'});});
 get('print-revision').addEventListener('click',()=>window.print());
 get('export-checks').addEventListener('click',()=>{const quote=v=>'"'+String(v).replaceAll('"','""')+'"';const rows=[['kind','self_check','ticked']];checks.forEach(c=>rows.push([c.dataset.kind,c.parentElement.textContent.trim(),c.checked?'yes':'no']));const blob=new Blob([rows.map(row=>row.map(quote).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='revision-self-checks.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
})();
